<?php
if (!isset($healthDimension, $healthPermission, $healthTitle)) {
    throw new RuntimeException('Health report configuration is missing.');
}
require_once __DIR__.'/../../../config/config.php';
require_once __DIR__.'/../../../helpers/auth.php';
require_once __DIR__.'/../../../helpers/permissions_v2.php';
require_once __DIR__.'/../../../helpers/report_pagination.php';
require_once __DIR__.'/../../../services/HealthEncounterService.php';
require_login();
$actorUserId=(int)($_SESSION['user_id']??0);$actorChurchId=(int)($_SESSION['church_id']??0);$superAdmin=is_super_admin();
if($actorChurchId<=0&&$actorUserId){$s=$conn->prepare('SELECT church_id FROM users WHERE id=?');$s->bind_param('i',$actorUserId);$s->execute();$actorChurchId=(int)($s->get_result()->fetch_assoc()['church_id']??0);$s->close();}
$service=new HealthEncounterService($conn,$actorUserId,$actorChurchId,$superAdmin);$churchId=$superAdmin?max(0,(int)($_GET['church_id']??$actorChurchId)):$actorChurchId;
if($churchId<=0||!$service->authorize($healthPermission,$churchId)){http_response_code(403);require __DIR__.'/../../errors/403.php';exit;}
$canExport=$service->authorize('export_health_report',$churchId);$from=preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['from_date']??''))?$_GET['from_date']:'';$to=preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['to_date']??''))?$_GET['to_date']:'';$selectedId=max(0,(int)($_GET['dimension_id']??0));$observationCode=(string)($_GET['observation_code']??'temperature');$definitions=HealthEncounterService::observationDefinitions();if(!isset($definitions[$observationCode]))$observationCode='temperature';
$where=['record.church_id=?','record.status<>"voided"'];$types='i';$params=[$churchId];if($from){$where[]='record.recorded_at>=?';$types.='s';$params[]=$from.' 00:00:00';}if($to){$where[]='record.recorded_at<?';$types.='s';$params[]=(new DateTimeImmutable($to))->modify('+1 day')->format('Y-m-d').' 00:00:00';}
$dimensionLabel="'All encounters'";$dimensionJoin='';$options=null;
if($healthDimension==='class'){$dimensionJoin=' LEFT JOIN bible_classes member_class ON member_class.id=member.class_id LEFT JOIN bible_classes child_class ON child_class.id=child.class_id ';$dimensionLabel="COALESCE(member_class.name,child_class.name,'Unassigned')";$optionsStmt=$conn->prepare('SELECT id,name FROM bible_classes WHERE church_id=? ORDER BY name');$optionsStmt->bind_param('i',$churchId);$optionsStmt->execute();$options=$optionsStmt->get_result();if($selectedId){$where[]='COALESCE(member.class_id,child.class_id)=?';$types.='i';$params[]=$selectedId;}}
elseif($healthDimension==='organization'){$dimensionLabel="COALESCE((SELECT GROUP_CONCAT(DISTINCT org.name ORDER BY org.name SEPARATOR ', ') FROM member_organizations membership JOIN organizations org ON org.id=membership.organization_id WHERE membership.member_id=record.member_id),'Not assigned')";$optionsStmt=$conn->prepare('SELECT id,name FROM organizations WHERE church_id=? ORDER BY name');$optionsStmt->bind_param('i',$churchId);$optionsStmt->execute();$options=$optionsStmt->get_result();if($selectedId){$where[]='EXISTS(SELECT 1 FROM member_organizations membership WHERE membership.member_id=record.member_id AND membership.organization_id=?)';$types.='i';$params[]=$selectedId;}}
else{$dimensionLabel="'".$conn->real_escape_string($definitions[$observationCode]['label'])."'";$where[]='EXISTS(SELECT 1 FROM health_observations chosen WHERE chosen.health_record_id=record.id AND chosen.observation_code=?)';$types.='s';$params[]=$observationCode;}
$whereSql=implode(' AND ',$where);
$sql="SELECT record.id,record.recorded_at,{$dimensionLabel} dimension_label,COALESCE(member.crn,child.srn) identifier,COALESCE(TRIM(CONCAT_WS(' ',member.first_name,member.middle_name,member.last_name)),TRIM(CONCAT_WS(' ',child.first_name,child.middle_name,child.last_name))) person_name,record.encounter_type,record.follow_up_status,
 (SELECT value_numeric FROM health_observations WHERE health_record_id=record.id AND observation_code='temperature' LIMIT 1) temperature,
 (SELECT value_numeric FROM health_observations WHERE health_record_id=record.id AND observation_code='blood_pressure_systolic' LIMIT 1) systolic,
 (SELECT value_numeric FROM health_observations WHERE health_record_id=record.id AND observation_code='blood_pressure_diastolic' LIMIT 1) diastolic,
 (SELECT value_numeric FROM health_observations WHERE health_record_id=record.id AND observation_code='blood_glucose' LIMIT 1) glucose,
 (SELECT value_numeric FROM health_observations WHERE health_record_id=record.id AND observation_code=? LIMIT 1) selected_value,
 (SELECT unit_code FROM health_observations WHERE health_record_id=record.id AND observation_code=? LIMIT 1) selected_unit
 FROM health_records record LEFT JOIN members member ON member.id=record.member_id LEFT JOIN sunday_school child ON child.id=record.sundayschool_id {$dimensionJoin} WHERE {$whereSql} ORDER BY record.recorded_at DESC,record.id DESC";
$queryTypes='ss'.$types;$queryParams=array_merge([$observationCode,$observationCode],$params);$pagination=report_paginate_query($conn,$sql,$queryTypes,$queryParams);$rows=$pagination['result'];$churches=$superAdmin?$conn->query('SELECT id,name FROM churches ORDER BY name'):null;$page_title=$healthTitle;ob_start();
?>
<link rel="stylesheet" href="<?= BASE_URL ?>/assets/css/health-workspace.css">
<div class="health-workspace"><form class="report-filter-panel health-filter mb-4" method="get"><div class="form-row"><?php if($superAdmin):?><div class="form-group col-lg-2"><label>Church</label><select name="church_id" class="form-control"><?php while($c=$churches->fetch_assoc()):?><option value="<?= $c['id'] ?>" <?= $churchId===(int)$c['id']?'selected':'' ?>><?= htmlspecialchars($c['name']) ?></option><?php endwhile;?></select></div><?php endif;?>
<?php if($healthDimension==='indicator'):?><div class="form-group col-lg-3"><label>Measurement</label><select class="form-control" name="observation_code"><?php foreach($definitions as $code=>$definition):?><option value="<?= $code ?>" <?= $observationCode===$code?'selected':'' ?>><?= htmlspecialchars($definition['label']) ?></option><?php endforeach;?></select></div><?php else:?><div class="form-group col-lg-3"><label><?= $healthDimension==='class'?'Bible Class':'Organization' ?></label><select class="form-control" name="dimension_id"><option value="">All</option><?php while($option=$options->fetch_assoc()):?><option value="<?= $option['id'] ?>" <?= $selectedId===(int)$option['id']?'selected':'' ?>><?= htmlspecialchars($option['name']) ?></option><?php endwhile;?></select></div><?php endif;?><div class="form-group col-lg-3"><label>From</label><input type="date" class="form-control" name="from_date" value="<?= htmlspecialchars($from) ?>"></div><div class="form-group col-lg-3"><label>To</label><input type="date" class="form-control" name="to_date" value="<?= htmlspecialchars($to) ?>"></div><div class="form-group col-lg-1 d-flex align-items-end"><button class="btn btn-primary btn-block"><i class="fas fa-filter"></i></button></div></div></form>
<div class="health-panel"><div class="health-panel-header"><div><h2 class="health-section-title"><?= htmlspecialchars($healthTitle) ?></h2><p class="health-section-copy"><?= number_format($pagination['total_rows']) ?> encounters; one row per encounter without organization duplication.</p></div></div><div class="table-responsive"><table id="healthDimensionTable" class="table health-table mb-0" data-report-pagination="server"><thead><tr><th>Date</th><th><?= $healthDimension==='indicator'?'Measurement':'Group' ?></th><th>Person</th><?php if($healthDimension==='indicator'):?><th>Value</th><?php endif;?><th>BP</th><th>Temperature</th><th>Glucose</th><th>Follow-up</th></tr></thead><tbody><?php while($row=$rows->fetch_assoc()):?><tr><td><?= date('d M Y H:i',strtotime($row['recorded_at'])) ?></td><td><?= htmlspecialchars($row['dimension_label']) ?></td><td><strong><?= htmlspecialchars($row['person_name']) ?></strong><br><small><?= htmlspecialchars($row['identifier']) ?></small></td><?php if($healthDimension==='indicator'):?><td><?= $row['selected_value']!==null?htmlspecialchars(rtrim(rtrim(number_format((float)$row['selected_value'],2,'.',''),'0'),'.').' '.$row['selected_unit']):'—' ?></td><?php endif;?><td><?= $row['systolic']!==null?(int)$row['systolic'].'/'.(int)$row['diastolic']:'—' ?></td><td><?= $row['temperature']!==null?number_format((float)$row['temperature'],1):'—' ?></td><td><?= $row['glucose']!==null?number_format((float)$row['glucose'],1):'—' ?></td><td><?= htmlspecialchars(ucfirst($row['follow_up_status'])) ?></td></tr><?php endwhile;?></tbody></table></div><div class="health-panel-body"><?php report_render_server_pagination($pagination['total_rows'],$pagination['page'],$pagination['per_page'],$healthTitle.' pages');?></div></div></div>
